 static String holderValue(Object value){if(value instanceof SByte[] a)return Integer.toString(a[0].get_Value());if(value instanceof Byte[] a)return Integer.toString(a[0].get_Value());if(value instanceof UInt16[] a)return Integer.toString(a[0].get_Value());if(value instanceof UInt32[] a)return Long.toString(a[0].get_Value());return Integer.toString(((Int32[])value)[0].get_Value());}
